595	  /**
596	   * Update an existing issue.
597	   *
598	   * Appends an update event to the issue file, recomputes state, and updates the index.
599	   * Handles hierarchy side effects: downward cascade (auto-close done children when parent
600	   * closes), upward promotion (promote parent when child advances past it), and reparenting
601	   * validation. Also auto-resolves active blockages when the issue transitions to done/closed.
602	   *
603	   * @param id - The issue ID to update
604	   * @param params - Update parameters (at least one field required besides author)
605	   * @param params.title - New title
606	   * @param params.description - New description
607	   * @param params.status - New status
608	   * @param params.assignee - New assignee, or null to clear
609	   * @param params.tags - New tags (replaces existing)
610	   * @param params.priority - New priority (1-5)
611	   * @param params.parentId - New parent ID, or null to detach
612	   * @param params.author - Override author (resolved by auth layer if not provided)
613	   * @returns `{ result: "OK" }` on success, or a AgentrackError on auth failure
614	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
615	   * @throws {AgentrackError} INVALID_PARAMS if no fields provided besides author
616	   * @throws {AgentrackError} NOT_FOUND if issue ID is not in the index
617	   * @throws {AgentrackError} ISSUE_MISSING if index entry exists but file is missing
618	   * @throws {AgentrackError} HIERARCHY_CONSTRAINT if status change violates parent/child rules
619	   *
620	   * @example
621	   * ```typescript
622	   * await tracker.update("abc123def4", { status: "in-progress", priority: 2 });
623	   * ```
624	   */
625	  async update(id: IssueId, params: UpdateParams): Promise<UpdateResult> {
626	    const trackerDir = resolveTrackerDir(this.cwd);
627	    if (!trackerDir) {
628	      throw new AgentrackError(
629	        ErrorCodes.NOT_INITIALIZED.result,
630	        "No .agentrack/ directory found. Run `agt init` first.",
631	        ErrorCodes.NOT_INITIALIZED.exitCode,
632	      );
633	    }
634	
635	    // Validate at least one field provided (besides author)
636	    const hasField =
637	      params.title !== undefined ||
638	      params.description !== undefined ||
639	      params.status !== undefined ||
640	      params.assignee !== undefined ||
641	      params.tags !== undefined ||
642	      params.priority !== undefined ||
643	      params.parentId !== undefined;
644	
645	    if (!hasField) {
646	      throw new AgentrackError(
647	        ErrorCodes.INVALID_PARAMS.result,
648	        "At least one field must be provided for update.",
649	        ErrorCodes.INVALID_PARAMS.exitCode,
650	      );
651	    }
652	
653	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
654	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
655	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
656	    if (authResult instanceof AgentrackError) return authResult;
657	    const author = params.author ?? authResult.author;
658	
659	    const index = await readIndex(trackerDir);
660	    const entry = findEntry(index, id);
661	    if (!entry) {
662	      throw new AgentrackError(
663	        ErrorCodes.NOT_FOUND.result,
664	        `Issue \`${id}\` not found in index.`,
665	        ErrorCodes.NOT_FOUND.exitCode,
666	      );
667	    }
668	
669	    const issueFilePath = join(trackerDir, entry.path);
670	    if (!existsSync(issueFilePath)) {
671	      throw new AgentrackError(
672	        ErrorCodes.ISSUE_MISSING.result,
673	        `Issue file for \`${id}\` is missing.`,
674	        ErrorCodes.ISSUE_MISSING.exitCode,
675	      );
676	    }
677	
678	    // Save old values for hierarchy handling
679	    const oldStatus = entry.status;
680	    const oldParentId = entry.parentId;
681	
682	    // ── Hierarchy validation (before any state changes) ────────────
683	
684	    // Validate downward constraints for status change
685	    if (params.status !== undefined && params.status !== oldStatus) {
686	      if (params.status === "done" || params.status === "closed") {
687	        const childIds = getChildren(index, id);
688	        const childEntries = childIds
689	          .map((cid) => findEntry(index, cid))
690	          .filter((e): e is IndexEntry => e !== null);
691	        const validationError = validateParentStatusChange(index, childEntries, params.status);
692	        if (validationError) {
693	          throw new AgentrackError(
694	            ErrorCodes.HIERARCHY_CONSTRAINT.result,
695	            validationError,
696	            ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
697	          );
698	        }
699	      }
700	    }
701	
702	    // Validate reparenting constraints
703	    if (params.parentId !== undefined && params.parentId !== oldParentId) {
704	      if (params.parentId !== null) {
705	        const newParentEntry = findEntry(index, params.parentId);
706	        if (!newParentEntry) {
707	          throw new AgentrackError(
708	            ErrorCodes.NOT_FOUND.result,
709	            `Parent issue \`${params.parentId}\` not found in index.`,
710	            ErrorCodes.NOT_FOUND.exitCode,
711	          );
712	        }
713	        const validationError = validateNewChild(newParentEntry);
714	        if (validationError) {
715	          throw new AgentrackError(
716	            ErrorCodes.HIERARCHY_CONSTRAINT.result,
717	            validationError,
718	            ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
719	          );
720	        }
721	      }
722	    }
723	
724	    // ── Build and append update event ──────────────────────────────
725	
726	    // Build update event content with only the provided fields
727	    const content: Partial<
728	      Pick<
729	        IssueProperties,
730	        "title" | "description" | "status" | "assignee" | "tags" | "priority" | "parentId"
731	      >
732	    > = {};
733	    if (params.title !== undefined) content.title = params.title;
734	    if (params.description !== undefined) content.description = params.description;
735	    if (params.status !== undefined) content.status = params.status;
736	    if (params.assignee !== undefined) content.assignee = params.assignee;
737	    if (params.tags !== undefined) content.tags = params.tags;
738	    if (params.priority !== undefined) content.priority = params.priority;
739	    if (params.parentId !== undefined) content.parentId = params.parentId;
740	
741	    const now = new Date().toISOString();
742	
743	    const updateEvent = {
744	      type: "update" as const,
745	      timestamp: now,
746	      author,
747	      content,
748	    };
749	
750	    // Append event to issue file
751	    await appendEvent(issueFilePath, updateEvent);
752	
753	    // Recompute state from all events
754	    const events = await replayEvents(issueFilePath);
755	    const computed = computeState(events, id);
756	
757	    // Update index entry with new computed values
758	    let updatedIndex = updateEntry(index, id, {
759	      title: computed.title,
760	      status: computed.status,
761	      assignee: computed.assignee,
762	      parentId: computed.parentId,
763	      tags: computed.tags,
764	      priority: computed.priority,
765	    });
766	
767	    // ── Hierarchy handling (after event append, before index write) ─
768	
769	    // 1. Handle reparenting (childrenOf updates)
770	    if (params.parentId !== undefined && params.parentId !== oldParentId) {
771	      // Detach from old parent
772	      if (oldParentId !== null) {
773	        updatedIndex = removeChild(updatedIndex, oldParentId, id);
774	      }
775	      // Attach to new parent
776	      if (params.parentId !== null) {
777	        updatedIndex = addChild(updatedIndex, params.parentId, id);
778	
779	        // Upward promotion for reparenting: if child's status is past new parent's status
780	        const newParentEntry = findEntry(updatedIndex, params.parentId);
781	        if (newParentEntry && isStatusAfter(computed.status, newParentEntry.status)) {
782	          const promotions = computeUpwardPromotions(
783	            updatedIndex,
784	            newParentEntry,
785	            computed.status,
786	            (iid) => findEntry(updatedIndex, iid),
787	          );
788	          for (const promo of promotions) {
789	            const promoEntry = findEntry(updatedIndex, promo.issueId);
790	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
791	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
792	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
793	                status: promo.event.content.status,
794	              });
795	            }
796	          }
797	        }
798	      }
799	    }
800	
801	    // 2. Handle status change
802	    if (params.status !== undefined && params.status !== oldStatus) {
803	      // Downward cascade: auto-close done children when parent closes
804	      if (params.status === "closed") {
805	        updatedIndex = await cascadeClose(updatedIndex, id, trackerDir);
806	      }
807	
808	      // Upward promotion: promote parent if child advanced past it
809	      const currentParentId = computed.parentId;
810	      if (currentParentId) {
811	        const parentEntry = findEntry(updatedIndex, currentParentId);
812	        if (parentEntry && isStatusAfter(params.status, parentEntry.status)) {
813	          const promotions = computeUpwardPromotions(
814	            updatedIndex,
815	            parentEntry,
816	            params.status,
817	            (iid) => findEntry(updatedIndex, iid),
818	          );
819	          for (const promo of promotions) {
820	            const promoEntry = findEntry(updatedIndex, promo.issueId);
821	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
822	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
823	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
824	                status: promo.event.content.status,
825	              });
826	            }
827	          }
828	        }
829	      }
830	    }
831	
832	    await writeIndex(trackerDir, updatedIndex);
833	
834	    // ── Auto-resolution: resolve active blockages when issue → done/closed ──
835	    if (params.status !== undefined && params.status !== oldStatus) {
836	      if (params.status === "done" || params.status === "closed") {
837	        const deps = await readDependencies(trackerDir);
838	        const activeBlocks = (deps.blocks[id] ?? []).filter((e) => e.status === "active");
839	
840	        if (activeBlocks.length > 0) {
841	          let updatedDeps = deps;
842	          for (const entry of activeBlocks) {
843	            updatedDeps = resolveBlockage(updatedDeps, entry.blockedId, entry.blockerId);
844	
845	            const blockedEntry = findEntry(updatedIndex, entry.blockedId);
846	            if (blockedEntry) {
847	              const now = new Date().toISOString();
848	              const resolveEvent: Event = {
849	                type: "blockage-resolved",
850	                timestamp: now,
851	                author: "system",
852	                content: {
853	                  blockerId: id,
854	                  reason: `Blocker issue ${id} transitioned to ${params.status}`,
855	                },
856	              };
857	              await appendEvent(join(trackerDir, blockedEntry.path), resolveEvent);
858	            }
859	          }
860	          await writeDependencies(trackerDir, updatedDeps);
861	        }
862	      }
863	    }
864	
865	    return { result: "OK" };
866	  }
