1246	    const trackerDir = resolveTrackerDir(this.cwd);
1247	    if (!trackerDir) {
1248	      throw new AgentrackError(
1249	        ErrorCodes.NOT_INITIALIZED.result,
1250	        "No .agentrack/ directory found. Run `agt init` first.",
1251	        ErrorCodes.NOT_INITIALIZED.exitCode,
1252	      );
1253	    }
1254	
1255	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
1256	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
1257	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
1258	    if (authResult instanceof AgentrackError) return authResult;
1259	    const author = params.author ?? authResult.author;
1260	
1261	    const index = await readIndex(trackerDir);
1262	
1263	    // Validate blockedId exists
1264	    if (!findEntry(index, blockedId)) {
1265	      throw new AgentrackError(
1266	        ErrorCodes.NOT_FOUND.result,
1267	        `Issue \`${blockedId}\` not found in index.`,
1268	        ErrorCodes.NOT_FOUND.exitCode,
1269	      );
1270	    }
1271	
1272	    // Validate all blockerIds exist
1273	    for (const blockerId of params.blockerIds) {
