1304	
1305	    // Append events to blockedId's issue file
1306	    const blockedEntry = findEntry(index, blockedId)!;
1307	    const issueFilePath = join(trackerDir, blockedEntry.path);
1308	
1309	    for (const blockerId of params.blockerIds) {
1310	      const now = new Date().toISOString();
1311	      const event: Event = {
1312	        type: "blockage-added",
1313	        timestamp: now,
1314	        author,
1315	        content: { blockerId },
1316	      };
1317	      await appendEvent(issueFilePath, event);
1318	    }
1319	
1320	    return { result: "OK" };
1321	  }
