    return replayEvents(issueFilePath);
  }

  // ─── Comments ─────────────────────────────────────────────────────

  /**
   * Add a comment to an issue.
   *
   * Appends a comment event to the issue file with a newly generated comment ID.
   *
   * @param id - The issue ID to comment on
