import type { CommentId, IssueId } from "../types";

/**
 * Generate a unique issue ID.
 * Format: 6 chars from timestamp (base36) + 4 random chars (base36) = 10 chars total.
 * IDs are sortable by creation time.
 */
export function generateId(): IssueId {
  return Date.now().toString(36).slice(0, 6) + Math.random().toString(36).slice(-4);
}

/**
 * Generate a unique comment ID.
 * Uses the same algorithm as issue IDs.
 */
export function generateCommentId(): CommentId {
  return Date.now().toString(36).slice(0, 6) + Math.random().toString(36).slice(-4);
}

// Issue-related types

// API types
export type {
  BlockagesAddParams,
  BlockagesAddResult,
  BlockagesDeleteParams,
  BlockagesDeleteResult,
  BlockagesListResult,
  BlockagesResolveParams,
  BlockagesResolveResult,
  CommentAddParams,
  CommentAddResult,
  CommentDeleteParams,
  CommentDeleteResult,
  CommentsListResult,
  CommentUpdateParams,
  CommentUpdateResult,
  CreateParams,
  CreateResult,
  HistoryResult,
  InitResult,
  ListParams,
  ListResult,
  NextResult,
  UpdateParams,
  UpdateResult,
  UsersListResult,
  UsersRegenerateResult,
  UsersRegisterResult,
  UsersRevokeResult,
  ViewResult,
  WorktreeInitResult,
  WorktreePullResult,
  WorktreeSyncResult,
} from "./api";
// Config types
export type { ConfigFile } from "./config";
// Dependency types
export type { BlockageEntry, BlockageInfo, DependenciesFile } from "./dependency";
// Event types
export type {
  BaseEvent,
  BlockageAddedEvent,
  BlockageDeletedEvent,
  BlockageResolvedEvent,
  CommentDeleteEvent,
  CommentEvent,
  CommentUpdateEvent,
  CreationEvent,
  Event,
  UpdateEvent,
} from "./event";
// Index file types
export type { IndexEntry, IndexFile } from "./index-file";
export type {
  CommentId,
  ComputedComment,
  ComputedIssue,
  IssueId,
  IssueProperties,
  IssueStatus,
} from "./issue";
// User types
export type { UserEntry, UserInfo, UsersFile } from "./user";

